    LEFT JOIN (SELECT s."SKU" AS "SKU", s."Versions" AS "Versions", s."Years" AS "Years", s.v AS v FROM "Standard Cost Plan" s) r0 ON r0."SKU" = d."SKU" AND r0."Versions" = d."Versions" AND r0."Years" = d."Years"
) WHERE v IS NOT NULL;
